import{_ as t,a,o as r,a6 as d}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse(`{"title":"Update Product Review","description":"","frontmatter":{"outline":false,"examples":[{"id":"update-product-review","title":"Update Product Review","description":"Edit a review the authenticated customer wrote. The method is PATCH and the body must be sent as merge-patch JSON.","request":"PATCH /api/shop/reviews/40\\nContent-Type: application/merge-patch+json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer 12|Iy8NExampleCustomerAccessToken\\n\\n{\\n  \\"title\\": \\"Great air fryer\\",\\n  \\"rating\\": 4\\n}\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 40,\\n  \\"name\\": \\"John Doe\\",\\n  \\"title\\": \\"Great air fryer\\",\\n  \\"rating\\": 4,\\n  \\"comment\\": \\"Very satisfied with this purchase. Great quality and fast delivery.\\",\\n  \\"status\\": \\"pending\\",\\n  \\"createdAt\\": \\"2026-08-07T16:04:39+05:30\\",\\n  \\"updatedAt\\": \\"2026-08-07T16:04:51+05:30\\"\\n}\\n","commonErrors":[{"error":"415 Unsupported Media Type","cause":"The request used Content-Type application/json","solution":"Send Content-Type application/merge-patch+json — this endpoint accepts nothing else"},{"error":"403 Forbidden — This review was not written by you","cause":"The review belongs to another customer, or to a guest","solution":"A review can only be edited by the customer who wrote it"},{"error":"403 Forbidden — Please login to manage your review","cause":"No customer Bearer token was sent","solution":"Log the customer in and retry"},{"error":"400 Bad Request — Rating must be between 1 and 5","cause":"rating fell outside 1–5","solution":"Send an integer from 1 to 5"},{"error":"404 Not Found","cause":"No review carries that ID","solution":"Use an ID returned when the review was created, or from the customer's own review list"}]}]},"headers":[],"relativePath":"api/rest-api/shop/product-reviews/update-product-review.md","filePath":"api/rest-api/shop/product-reviews/update-product-review.md","lastUpdated":1786429091000}`),i={name:"api/rest-api/shop/product-reviews/update-product-review.md"};function o(s,e,n,h,p,c){return r(),a("div",null,e[0]||(e[0]=[d(`<h1 id="update-product-review" tabindex="-1">Update Product Review <a class="header-anchor" href="#update-product-review" aria-label="Permalink to &quot;Update Product Review&quot;">​</a></h1><p>Edit a review the authenticated customer wrote.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PATCH /api/shop/reviews/{reviewId}</span></span></code></pre></div><p>The verb is <code>PATCH</code>, and the body must carry <code>Content-Type: application/merge-patch+json</code>. <code>PUT</code> is not routed, and a plain <code>application/json</code> body is rejected with <code>415</code>.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td><code>application/merge-patch+json</code></td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token of the customer who wrote the review</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path Parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>reviewId</code></td><td>integer</td><td>Yes</td><td>The review to edit. No product ID is part of the path.</td></tr></tbody></table><h2 id="request-body" tabindex="-1">Request Body <a class="header-anchor" href="#request-body" aria-label="Permalink to &quot;Request Body&quot;">​</a></h2><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Great air fryer&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;rating&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>title</code></td><td>string</td><td>No</td><td>New headline.</td></tr><tr><td><code>comment</code></td><td>string</td><td>No</td><td>New body text.</td></tr><tr><td><code>rating</code></td><td>integer</td><td>No</td><td>New star rating, 1 to 5.</td></tr><tr><td><code>name</code></td><td>string</td><td>No</td><td>New display name.</td></tr></tbody></table><p>Every field is optional — the update is a partial patch, and anything omitted keeps its stored value.</p><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><p>The updated review, flat — the same shape <a href="/api/rest-api/shop/product-reviews/create-product-review.html">Create</a> returns.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Review ID.</td></tr><tr><td><code>name</code></td><td>string</td><td>Display name.</td></tr><tr><td><code>title</code> / <code>comment</code></td><td>string</td><td>Review text after the edit.</td></tr><tr><td><code>rating</code></td><td>integer</td><td>Star rating after the edit.</td></tr><tr><td><code>status</code></td><td>string</td><td>Moderation status. Editing does not reset it.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>ISO 8601 timestamps; only <code>updatedAt</code> moves.</td></tr></tbody></table><h2 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h2><p>A review may only be edited by the customer who wrote it. The check is on the stored author, not on the token alone, so:</p><ul><li>Another customer&#39;s review answers <code>403</code>.</li><li>A review submitted by a guest carries no author and can never be edited — also <code>403</code>.</li><li>Editing an already-approved review leaves it approved; the store&#39;s moderation status is untouched.</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>&quot;Edit your review&quot; on a product page</strong> — send only the changed fields; the response carries the full row for immediate re-render.</li><li><strong>Fix a wrong rating without retyping the text</strong> — a body of <code>{&quot;rating&quot;: 4}</code> alone is valid.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Set the merge-patch content type</strong> — sending <code>application/json</code> is the most common failure here and returns <code>415</code> rather than a validation error.</li><li><strong>Do not resend the whole review</strong> — a partial body avoids overwriting text the shopper edited in another tab.</li><li><strong>Expect the status to stay as it was</strong> — an edit is not resubmitted for approval, so an approved review stays live with the new text.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/product-reviews/create-product-review.html">Create Product Review</a> — submit a review; it starts as pending</li><li><a href="/api/rest-api/shop/product-reviews/delete-product-review.html">Delete Product Review</a> — remove the customer&#39;s own review</li><li><a href="/api/rest-api/shop/product-reviews/get-product-review.html">Get Product Review</a> — one review by id, whatever its status</li></ul>`,25)]))}const w=t(i,[["render",o]]);export{u as __pageData,w as default};
